124	// 完整顺序必须是 乙1、丙1、甲1、甲2、丁1：
125	// 甲2 不能凭最大费用越过甲1；甲1 入选后甲2 立即压过丁1，而不是被固定排在最后。
126	func TestProposeSequenceGatingAtFeeBoundaries(t *testing.T) {
127		keys := genKeys(t, 4)
128		n, _ := newTestNode(t, keys, 5)
129	
130		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
131		a2 := NewTransaction(keys[0].priv, 2, []byte("a2-max"), feeUintMax, 100)
132		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), feeHighBit, 100)
133		c1 := NewTransaction(keys[2].priv, 1, []byte("c1"), feeIntMax, 100)
134		d1 := NewTransaction(keys[3].priv, 1, []byte("d1-zero"), feeZero, 100)
135		for _, tx := range []*Transaction{a2, d1, a1, c1, b1} {
136			if _, err := n.Submit(tx); err != nil {
137				t.Fatal(err)
138			}
139		}
140	
141		assertProposalOrder(t, n, []string{b1.ID(), c1.ID(), a1.ID(), a2.ID(), d1.ID()})
142	
143		// 甲的两笔按序号先后都已选入；丁的 0 费用交易最后入选，均等待投票。
144		assertAccountQueue(t, n, keys[0].pub, 0, map[string]string{
145			a1.ID(): "waiting-vote", a2.ID(): "waiting-vote",
146		})
147		assertAccountQueue(t, n, keys[1].pub, 0, map[string]string{b1.ID(): "waiting-vote"})
148		assertAccountQueue(t, n, keys[2].pub, 0, map[string]string{c1.ID(): "waiting-vote"})
149		assertAccountQueue(t, n, keys[3].pub, 0, map[string]string{d1.ID(): "waiting-vote"})
150	}
151	
152	// 两笔可选交易费用相同且都处在高数值范围时，按完整交易标识字典序决定先后；
153	// 提交顺序与账户公钥顺序都不得影响结果。为同时证伪“公钥顺序定序”，刻意让
154	// 标识更小的交易来自公钥十六进制更大的账户。2^63 与 2^64-1 两个高值各验一次，
155	// 防止同费比较在最高位附近被误判成大小关系。
156	func TestProposeHighFeeTieBreakByTxID(t *testing.T) {
157		for _, fee := range []uint64{feeHighBit, feeUintMax} {
158			t.Run(fmt.Sprintf("fee-%d", fee), func(t *testing.T) {
159				keys := genKeys(t, 6)
160	
161				// 选出公钥十六进制最小与最大的两个账户。
162				ordered := append([]testKey(nil), keys...)
163				sort.Slice(ordered, func(i, j int) bool {
