package consensus

import (
	"crypto/ed25519"
	"crypto/rand"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"testing"
)

type testKey struct {
	priv ed25519.PrivateKey
	pub  ed25519.PublicKey
}

func genKeys(t *testing.T, n int) []testKey {
	t.Helper()
	keys := make([]testKey, n)
	for i := range keys {
		pub, priv, err := ed25519.GenerateKey(rand.Reader)
		if err != nil {
			t.Fatal(err)
		}
		keys[i] = testKey{priv: priv, pub: pub}
	}
	return keys
}

func newTestNode(t *testing.T, keys []testKey, maxTxs uint64) (*Node, string) {
	t.Helper()
	dir := t.TempDir()
	vals := make([][]byte, len(keys))
	for i, k := range keys {
		vals[i] = k.pub
	}
	n, err := New(dir, Config{Seed: []byte("test-seed-v1"), Validators: vals, MaxTxsPerBlock: maxTxs})
	if err != nil {
		t.Fatal(err)
	}
	return n, dir
}

func reason(err error) string {
	var re *RejectError
	if errors.As(err, &re) {
		return re.Reason
	}
	return ""
}

// 初始状态：轮次 1，账户确认序号 0，配置必须校验。
func TestInitialState(t *testing.T) {
	keys := genKeys(t, 4)
	n, _ := newTestNode(t, keys, 10)
	if n.CurrentRound() != 1 {
		t.Fatalf("initial round = %d, want 1", n.CurrentRound())
	}
	if n.Height() != 0 {
		t.Fatalf("initial height = %d, want 0", n.Height())
	}
	acct := n.Account(keys[0].pub)
	if acct.ConfirmedSequence != 0 {
		t.Fatalf("initial confirmed seq = %d, want 0", acct.ConfirmedSequence)
	}
	if acct.Gap != 0 || len(acct.Pending) != 0 {
		t.Fatalf("unexpected pending: %+v", acct)
	}

	dir := t.TempDir()
	cfg := Config{Seed: []byte("s"), Validators: [][]byte{keys[0].pub}, MaxTxsPerBlock: 1}
	if _, err := New(dir, Config{Validators: cfg.Validators, MaxTxsPerBlock: 1}); err == nil {
		t.Fatal("empty seed should be rejected")
	}
	if _, err := New(t.TempDir(), Config{Seed: []byte("s"), MaxTxsPerBlock: 1}); err == nil {
		t.Fatal("empty validators should be rejected")
	}
	if _, err := New(t.TempDir(), Config{Seed: []byte("s"), Validators: cfg.Validators, MaxTxsPerBlock: 0}); err == nil {
		t.Fatal("zero max txs should be rejected")

package consensus

import (
	"bytes"
	"fmt"
	"testing"
)

// assertTxMatches 校验查询返回的交易与提交时的原交易逐字段一致：
// 发送者、序号、内容、费用、到期轮次、签名相同，标识对应，签名仍有效。
func assertTxMatches(t *testing.T, got, want *Transaction) {
	t.Helper()
	if got == nil {
		t.Fatal("query returned nil transaction")
	}
	if !bytes.Equal(got.Sender, want.Sender) ||
		got.Sequence != want.Sequence ||
		!bytes.Equal(got.Content, want.Content) ||
		got.Fee != want.Fee ||
		got.Expiry != want.Expiry ||
		!bytes.Equal(got.Signature, want.Signature) {
		t.Fatalf("tx = {sender:%x seq:%d content:%q fee:%d expiry:%d sig:%x}, want {sender:%x seq:%d content:%q fee:%d expiry:%d sig:%x}",
			got.Sender, got.Sequence, got.Content, got.Fee, got.Expiry, got.Signature,
			want.Sender, want.Sequence, want.Content, want.Fee, want.Expiry, want.Signature)
	}
	if got.ID() != want.ID() {
		t.Fatalf("tx id = %s, want %s", got.ID(), want.ID())
	}
	if !got.Verify() {
		t.Fatal("stored transaction signature no longer verifies")
	}
}

// tamperQueryTx 以调用方身份尽力改写手中查询结果里的交易：
// 发送者公钥、内容、签名、费用、序号、到期轮次全部改写。
func tamperQueryTx(tx *Transaction) {
	tx.Sender[0] ^= 0xff
	tx.Content = append(tx.Content, "tampered"...)
	tx.Signature[0] ^= 0xff
	tx.Fee += 1000

