		t.Fatal("test setup: crafted id must be larger than the zero-fee victim")
	}
	s.assertRejected(t, loser)

	// 费用 1 严格高于 0：挤出 0 费用交易，且只挤出它。
	nk2 := genKeys(t, 1)[0]
	win := NewTransaction(nk2.priv, 1, []byte("fee-one"), 1, 100)
	s.assertAccepted(t, nk2, win, zero)
